<?php

namespace App\Http\Controllers\Api;

use App\Http\Controllers\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;

class PaymentController extends Controller
{
    public function upload(string $kode, Request $request) { $data=$request->validate(['no_hp'=>'required','metode_pembayaran'=>'nullable|string|max:100','bukti'=>'required|file|mimes:jpg,jpeg,png|max:5120']); $b=DB::table('booking')->join('pelanggan','pelanggan.id_pelanggan','=','booking.id_pelanggan')->where('kode_booking',$kode)->where('no_hp',$data['no_hp'])->select('booking.*')->first(); abort_unless($b,404); if($b->status_booking!=='Menunggu DP'||now()->greaterThan($b->batas_waktu_dp)) throw ValidationException::withMessages(['booking'=>'Booking tidak dapat menerima DP.']); if (DB::table('pembayaran')->where('id_booking', $b->id_booking)->where('jenis_pembayaran', 'DP')->whereIn('status_verifikasi', ['Menunggu Verifikasi', 'Terverifikasi'])->exists()) throw ValidationException::withMessages(['booking' => 'Bukti DP sudah diunggah.']); $path=$request->file('bukti')->store('bukti-dp','public'); $id=DB::table('pembayaran')->insertGetId(['id_booking'=>$b->id_booking,'jenis_pembayaran'=>'DP','nominal'=>$b->total_biaya/2,'metode_pembayaran'=>$data['metode_pembayaran'] ?? 'Transfer Bank','bukti_transfer_url'=>$path,'tanggal_pembayaran'=>now()]); return response()->json(['id_pembayaran'=>$id,'status_verifikasi'=>'Menunggu Verifikasi'],201); }
    public function pending() { return DB::table('pembayaran')->join('booking','booking.id_booking','=','pembayaran.id_booking')->where('jenis_pembayaran','DP')->where('status_verifikasi','Menunggu Verifikasi')->select('pembayaran.*','booking.kode_booking','booking.total_biaya')->get(); }
    public function verify(int $id, Request $request) { $status=$request->validate(['status'=>'required|in:Terverifikasi,Ditolak'])['status']; return DB::transaction(function() use($id,$status,$request) { $p=DB::table('pembayaran')->where('id_pembayaran', $id)->lockForUpdate()->first(); abort_unless($p,404); DB::table('pembayaran')->where('id_pembayaran',$id)->update(['status_verifikasi'=>$status,'diverifikasi_oleh'=>$request->attributes->get('pengguna')->id_pengguna]); if($status==='Terverifikasi') DB::table('booking')->where('id_booking',$p->id_booking)->update(['status_booking'=>'DP Terverifikasi']); DB::table('log_aktivitas')->insert(['id_pengguna'=>$request->attributes->get('pengguna')->id_pengguna,'id_booking'=>$p->id_booking,'aktivitas'=>'Verifikasi DP','detail_aktivitas'=>$status,'waktu_aktivitas'=>now()]); return ['status'=>$status]; }); }
    public function settle(string $kode, Request $request) { $admin=$request->attributes->get('pengguna'); return DB::transaction(function() use($kode,$request,$admin) { $b=DB::table('booking')->where('kode_booking',$kode)->lockForUpdate()->first(); abort_unless($b && $b->status_booking==='DP Terverifikasi',422,'Booking belum dapat dilunasi.'); $paid=DB::table('pembayaran')->where('id_booking',$b->id_booking)->where('status_verifikasi','Terverifikasi')->sum('nominal'); $remaining=(float)$b->total_biaya-(float)$paid; $nominal=(float)$request->validate(['nominal'=>'required|numeric'])['nominal']; if(abs($remaining-$nominal)>0.01) throw ValidationException::withMessages(['nominal'=>'Nominal harus sama dengan sisa tagihan.']); DB::table('pembayaran')->insert(['id_booking'=>$b->id_booking,'jenis_pembayaran'=>'Pelunasan','nominal'=>$nominal,'status_verifikasi'=>'Terverifikasi','metode_pembayaran'=>'Tunai','diverifikasi_oleh'=>$admin->id_pengguna,'tanggal_pembayaran'=>now()]); DB::table('booking')->where('id_booking',$b->id_booking)->update(['status_booking'=>'Lunas']); DB::table('log_aktivitas')->insert(['id_pengguna'=>$admin->id_pengguna,'id_booking'=>$b->id_booking,'aktivitas'=>'Pelunasan tunai','waktu_aktivitas'=>now()]); return ['status_booking'=>'Lunas']; }); }
}
